  1: { overall: "\uAE30\uC6B4\uC774 \uD06C\uAC8C \uBED7\uB294 \uB0A0\uC774\uC5D0\uC694. \uB2F9\uB2F9\uD558\uAC8C \uC55E\uC7A5\uC11C\uB418 \uD568\uAED8 \uAC00\uB294 \uC0AC\uB78C\uC744 \uCC59\uAE30\uC138\uC694.", wealth: "\uC218\uC785\uC774 \uB298\uACE0 \uAE30\uD68C\uAC00 \uC5F4\uB824\uC694. \uD070 \uD22C\uC790\uBCF4\uB2E4 \uC2E4\uB825\uC73C\uB85C \uBC8C \uB54C\uC785\uB2C8\uB2E4.", love: "\uC801\uADF9\uC801\uC73C\uB85C \uB2E4\uAC00\uAC00\uBA74 \uD1B5\uD574\uC694. \uB2E4\uB9CC \uBC00\uC5B4\uBD99\uC774\uAE30\uB9CC \uD558\uBA74 \uC0C1\uB300\uAC00 \uC9C0\uCE69\uB2C8\uB2E4.", exam: "\uC2E4\uB825\uC774 \uC815\uC810\uC774\uC5D0\uC694. \uC790\uC2E0 \uC788\uAC8C \uBCF4\uB418 \uB9C8\uC9C0\uB9C9 \uAC80\uD1A0\uB97C \uC78A\uC9C0 \uB9C8\uC138\uC694.", contract: "\uC8FC\uB3C4\uAD8C\uC774 \uB0B4\uAC8C \uC788\uC5B4\uC694. \uC870\uAC74\uC744 \uBD84\uBA85\uD788 \uD558\uACE0 \uBA3C\uC800 \uC81C\uC548\uD558\uC138\uC694.", health: "\uC5D0\uB108\uC9C0\uAC00 \uB118\uCCD0\uC694. \uACFC\uB85C\uB9CC \uC870\uC2EC\uD558\uBA74 \uC88B\uC2B5\uB2C8\uB2E4." },
